int xc2028_set_config(struct dvb_frontend *fe, void *priv_cfg) {
    struct xc2028_priv *priv = fe->demodulator_priv;
    struct xc2028_config *cfg = priv_cfg;
    int ret = 0;

    if (!fe || !priv_cfg) {
        return -EINVAL;
    }

    mutex_lock(&priv->lock);

    if (strcmp(priv->firmware_name, cfg->firmware_name) != 0) {
        if (priv->firmware_name) {
            kfree(priv->firmware_name);
        }
        priv->firmware_name = kstrdup(cfg->firmware_name, GFP_KERNEL);
        if (!priv->firmware_name) {
            ret = -ENOMEM;
            goto unlock;
        }
    }

    if (priv->state == XC2028_TUNER_IDLE) {
        ret = request_firmware_nowait(THIS_MODULE, 1, priv->firmware_name, fe->dvb->adapter->num, fe, &priv->firmware, NULL);
        if (ret < 0) {
            goto unlock;
        }
    }

unlock:
    mutex_unlock(&priv->lock);
    return ret;
}
